#pragma once
#include <string>
#include <stdexcept>
#include <vector>

// ---------------------------------------------------------------------------
// Error types
// ---------------------------------------------------------------------------

struct LexError : std::runtime_error {
    int line, col;
    LexError(const std::string& msg, int l, int c)
        : std::runtime_error(msg), line(l), col(c) {}
};

struct ParseError : std::runtime_error {
    int line, col;
    ParseError(const std::string& msg, int l, int c)
        : std::runtime_error(msg), line(l), col(c) {}
};

struct CodeGenError : std::runtime_error {
    explicit CodeGenError(const std::string& msg)
        : std::runtime_error(msg) {}
};

// ---------------------------------------------------------------------------
// Diagnostic record — collectable, non-throwing
// ---------------------------------------------------------------------------

enum class Severity { Error, Warning, Note };

struct Diagnostic {
    Severity    severity;
    std::string message;
    std::string hint;    // optional contextual hint / "did you mean?"
    int         line;
    int         col;
};

// ---------------------------------------------------------------------------
// ErrorCollector — gathers multiple diagnostics before aborting
// ---------------------------------------------------------------------------

struct ErrorCollector {
    std::vector<Diagnostic> items;
    int maxErrors = 20;

    void add(Severity s, const std::string& msg, int line, int col,
             const std::string& hint = "") {
        items.push_back({ s, msg, hint, line, col });
    }

    void error(const std::string& msg, int line, int col,
               const std::string& hint = "") {
        add(Severity::Error, msg, line, col, hint);
        if (errorCount() >= maxErrors)
            throw ParseError("too many errors (" + std::to_string(maxErrors)
                             + "), aborting", line, col);
    }

    int errorCount() const {
        int n = 0;
        for (const auto& d : items) if (d.severity == Severity::Error) ++n;
        return n;
    }

    bool hasErrors() const { return errorCount() > 0; }

    // Print all diagnostics to stderr.
    void dump(const std::string& filename = "") const;
};

// ---------------------------------------------------------------------------
// Formatting helpers
// ---------------------------------------------------------------------------

inline std::string severityLabel(Severity s) {
    switch (s) {
        case Severity::Error:   return "error";
        case Severity::Warning: return "warning";
        case Severity::Note:    return "note";
    }
    return "error";
}

inline std::string formatDiag(const std::string& kind,
                               const std::string& msg,
                               int line, int col) {
    return kind + " at line " + std::to_string(line)
         + ", col "  + std::to_string(col)
         + ": "      + msg;
}

inline std::string formatDiagnostic(const Diagnostic& d,
                                    const std::string& filename = "") {
    std::string out;
    if (!filename.empty()) out += filename + ":";
    out += std::to_string(d.line) + ":" + std::to_string(d.col)
        + ": " + severityLabel(d.severity) + ": " + d.message;
    if (!d.hint.empty()) out += "\n  hint: " + d.hint;
    return out;
}

#pragma once
#include "ast.h"
#include <string>

// ---------------------------------------------------------------------------
// CodeGenOptions — configures how JSX is lowered
// ---------------------------------------------------------------------------

enum class JSXPragma {
    React,      // React.createElement(...)  [default]
    H,          // h(...)                    [Preact / hyperscript]
    JSX,        // _jsx(...)                 [React 17 classic runtime alias]
    AutoImport, // React 17+ automatic runtime: import {jsx as _jsx} from 'react/jsx-runtime'
};

struct CodeGenOptions {
    JSXPragma pragma       = JSXPragma::React;
    bool      devMode      = false;   // emit __source / __self props
    bool      minify       = false;   // future: compact output
    int       indentWidth  = 2;

    // Pragma call as string: "React.createElement", "h", "_jsx", "_jsx"
    std::string pragmaCall() const {
        switch (pragma) {
            case JSXPragma::React:      return "React.createElement";
            case JSXPragma::H:          return "h";
            case JSXPragma::JSX:        return "_jsx";
            case JSXPragma::AutoImport: return "_jsx";
        }
        return "React.createElement";
    }

    // Fragment expression: "React.Fragment", "Fragment", etc.
    std::string fragmentExpr() const {
        switch (pragma) {
            case JSXPragma::React:      return "React.Fragment";
            case JSXPragma::H:          return "Fragment";
            case JSXPragma::JSX:        return "_Fragment";
            case JSXPragma::AutoImport: return "_Fragment";
        }
        return "React.Fragment";
    }
};

// ---------------------------------------------------------------------------
// CodeGen — walks the AST and emits JavaScript source text.
// JSX nodes are lowered using the configured pragma.
// ---------------------------------------------------------------------------
class CodeGen {
public:
    explicit CodeGen(CodeGenOptions opts = {});

    std::string generate(const Node& program, const std::string& filename = "");

private:
    CodeGenOptions opts_;
    int            indentLevel_ = 0;
    std::string    out_;
    std::string    filename_;   // for __source dev prop

    // --- emit helpers ---
    void emit(const std::string& s);
    void emitLine(const std::string& s = "");
    void indent();
    void dedent();
    std::string indentStr() const;

    // --- node visitors ---
    void genNode(const Node& n);
    void genProgram(const Node& n);

    // statements
    void genImportDecl(const Node& n);
    void genExportDefaultDecl(const Node& n);
    void genExportNamedDecl(const Node& n);
    void genFunctionDecl(const Node& n);
    void genBlockStmt(const Node& n);
    void genReturnStmt(const Node& n);
    void genIfStmt(const Node& n);
    void genForStmt(const Node& n);
    void genWhileStmt(const Node& n);
    void genVarDecl(const Node& n);
    void genExprStmt(const Node& n);

    // expressions
    void genExpr(const Node& n);
    void genIdentifier(const Node& n);
    void genNumericLiteral(const Node& n);
    void genStringLiteral(const Node& n);
    void genTemplateLiteral(const Node& n);
    void genBoolLiteral(const Node& n);
    void genBinaryExpr(const Node& n);
    void genUnaryExpr(const Node& n);
    void genLogicalExpr(const Node& n);
    void genAssignExpr(const Node& n);
    void genCallExpr(const Node& n);
    void genMemberExpr(const Node& n);
    void genNewExpr(const Node& n);
    void genConditionalExpr(const Node& n);
    void genSpreadElement(const Node& n);
    void genArrayExpr(const Node& n);
    void genObjectExpr(const Node& n);
    void genArrowFunctionExpr(const Node& n);
    void genSequenceExpr(const Node& n);

    // JSX lowering
    void genJSXElement(const Node& n);
    void genJSXFragment(const Node& n);
    void genJSXChild(const Node& n);

    void emitJSXProps(const Node& openingEl);
    void emitAutoImport(); // React 17+ runtime import

    static std::string escapeJSXText(const std::string& raw);
    static std::string escapeString(const std::string& s);
};

#include "codegen.h"
#include "diagnostics.h"
#include <sstream>
#include <stdexcept>

// ---------------------------------------------------------------------------
// Construction
// ---------------------------------------------------------------------------
CodeGen::CodeGen(CodeGenOptions opts) : opts_(opts) {}

// ---------------------------------------------------------------------------
// Emit helpers
// ---------------------------------------------------------------------------
void CodeGen::emit(const std::string& s)     { out_ += s; }
void CodeGen::emitLine(const std::string& s) { out_ += s + "\n"; }
void CodeGen::indent()  { ++indentLevel_; }
void CodeGen::dedent()  { if (indentLevel_ > 0) --indentLevel_; }

std::string CodeGen::indentStr() const {
    return std::string(indentLevel_ * opts_.indentWidth, ' ');
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------
std::string CodeGen::generate(const Node& program, const std::string& filename) {
    out_.clear();
    indentLevel_ = 0;
    filename_    = filename;

    if (opts_.pragma == JSXPragma::AutoImport)
        emitAutoImport();

    genProgram(program);
    return out_;
}

// ---------------------------------------------------------------------------
// Auto-import for React 17+ automatic runtime
// ---------------------------------------------------------------------------
void CodeGen::emitAutoImport() {
    emitLine("import { jsx as _jsx, jsxs as _jsxs, Fragment as _Fragment } from \"react/jsx-runtime\";");
}

// ---------------------------------------------------------------------------
// String escaping
// ---------------------------------------------------------------------------
std::string CodeGen::escapeString(const std::string& s) {
    std::string out;
    for (char c : s) {
        switch (c) {
            case '"':  out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n";  break;
            case '\r': out += "\\r";  break;
            case '\t': out += "\\t";  break;
            default:   out += c;
        }
    }
    return out;
}

// Normalise JSX text: collapse whitespace runs to single spaces.
std::string CodeGen::escapeJSXText(const std::string& raw) {
    std::string s;
    bool prevSpace = true;
    for (char c : raw) {
        if (std::isspace((unsigned char)c)) {
            if (!prevSpace) { s += ' '; prevSpace = true; }
        } else {
            s += c;
            prevSpace = false;
        }
    }
    if (!s.empty() && s.back() == ' ' && !raw.empty() &&
        (raw.back() == '\n' || raw.back() == '\r'))
        s.pop_back();
    return s;
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------
void CodeGen::genNode(const Node& n) {
    switch (n.kind) {
        case NodeKind::Program:          genProgram(n);          break;
        case NodeKind::ImportDecl:       genImportDecl(n);       break;
        case NodeKind::ExportDefaultDecl:genExportDefaultDecl(n);break;
        case NodeKind::ExportNamedDecl:  genExportNamedDecl(n);  break;
        case NodeKind::FunctionDecl:     genFunctionDecl(n);     break;
        case NodeKind::BlockStmt:        genBlockStmt(n);        break;
        case NodeKind::ReturnStmt:       genReturnStmt(n);       break;
        case NodeKind::IfStmt:           genIfStmt(n);           break;
        case NodeKind::ForStmt:          genForStmt(n);          break;
        case NodeKind::WhileStmt:        genWhileStmt(n);        break;
        case NodeKind::VarDecl:          genVarDecl(n);          break;
        case NodeKind::ExprStmt:         genExprStmt(n);         break;
        default:                         genExpr(n);             break;
    }
}

void CodeGen::genProgram(const Node& n) {
    for (const auto& stmt : n.body) {
        emit(indentStr());
        genNode(*stmt);
        emitLine();
    }
}

// ---------------------------------------------------------------------------
// Statements
// ---------------------------------------------------------------------------
void CodeGen::genImportDecl(const Node& n) {
    emit("import ");
    if (n.specifiers.empty()) {
        // side-effect import
    } else if (n.specifiers.size() == 1 && n.specifiers[0]->name == "*") {
        emit("* as " + n.specifiers[0]->value);
    } else {
        bool first = true;
        emit("{ ");
        for (const auto& s : n.specifiers) {
            if (!first) emit(", ");
            first = false;
            emit(s->name);
            if (!s->value.empty()) emit(" as " + s->value);
        }
        emit(" }");
    }
    if (!n.source.empty()) emit(" from \"" + n.source + "\"");
    emit(";");
}

void CodeGen::genExportDefaultDecl(const Node& n) {
    emit("export default ");
    genNode(*n.declaration);
    if (n.declaration->kind != NodeKind::FunctionDecl)
        emit(";");
}

void CodeGen::genExportNamedDecl(const Node& n) {
    emit("export ");
    if (!n.specifiers.empty()) {
        emit("{ ");
        for (size_t i = 0; i < n.specifiers.size(); ++i) {
            if (i) emit(", ");
            emit(n.specifiers[i]->name);
            if (!n.specifiers[i]->value.empty())
                emit(" as " + n.specifiers[i]->value);
        }
        emit(" }");
        if (!n.source.empty()) emit(" from \"" + n.source + "\"");
        emit(";");
    } else if (n.declaration) {
        genNode(*n.declaration);
    }
}

void CodeGen::genFunctionDecl(const Node& n) {
    if (n.async_) emit("async ");
    emit("function");
    if (!n.name.empty()) emit(" " + n.name);
    emit("(");
    for (size_t i = 0; i < n.params.size(); ++i) {
        if (i) emit(", ");
        emit(n.params[i]->name);
    }
    emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genBlockStmt(const Node& n) {
    emitLine("{");
    indent();
    for (const auto& stmt : n.body) {
        emit(indentStr());
        genNode(*stmt);
        emitLine();
    }
    dedent();
    emit(indentStr() + "}");
}

void CodeGen::genReturnStmt(const Node& n) {
    emit("return");
    if (n.expression) { emit(" "); genExpr(*n.expression); }
    emit(";");
}

void CodeGen::genIfStmt(const Node& n) {
    emit("if ("); genExpr(*n.test); emit(") ");
    genNode(*n.consequent);
    if (n.alternate) { emit(" else "); genNode(*n.alternate); }
}

void CodeGen::genForStmt(const Node& n) {
    emit("for (");
    if (n.init)   genNode(*n.init);  else emit(";");
    emit(" ");
    if (n.test)   genExpr(*n.test);
    emit("; ");
    if (n.update) genExpr(*n.update);
    emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genWhileStmt(const Node& n) {
    emit("while ("); genExpr(*n.test); emit(") ");
    if (!n.body.empty()) genNode(*n.body[0]);
}

void CodeGen::genVarDecl(const Node& n) {
    emit(n.varKind + " ");
    for (size_t i = 0; i < n.declarations.size(); ++i) {
        if (i) emit(", ");
        const Node& d = *n.declarations[i];
        emit(d.name);
        if (d.init) { emit(" = "); genExpr(*d.init); }
    }
    emit(";");
}

void CodeGen::genExprStmt(const Node& n) {
    genExpr(*n.expression);
    emit(";");
}

// ---------------------------------------------------------------------------
// Expressions
// ---------------------------------------------------------------------------
void CodeGen::genExpr(const Node& n) {
    switch (n.kind) {
        case NodeKind::Identifier:          genIdentifier(n);       break;
        case NodeKind::NumericLiteral:      genNumericLiteral(n);   break;
        case NodeKind::StringLiteral:       genStringLiteral(n);    break;
        case NodeKind::TemplateLiteral:     genTemplateLiteral(n);  break;
        case NodeKind::BoolLiteral:         genBoolLiteral(n);      break;
        case NodeKind::NullLiteral:         emit("null");            break;
        case NodeKind::BinaryExpr:          genBinaryExpr(n);       break;
        case NodeKind::UnaryExpr:           genUnaryExpr(n);        break;
        case NodeKind::LogicalExpr:         genLogicalExpr(n);      break;
        case NodeKind::AssignExpr:          genAssignExpr(n);       break;
        case NodeKind::CallExpr:            genCallExpr(n);         break;
        case NodeKind::MemberExpr:          genMemberExpr(n);       break;
        case NodeKind::NewExpr:             genNewExpr(n);          break;
        case NodeKind::ConditionalExpr:     genConditionalExpr(n);  break;
        case NodeKind::SpreadElement:       genSpreadElement(n);    break;
        case NodeKind::ArrayExpr:           genArrayExpr(n);        break;
        case NodeKind::ObjectExpr:          genObjectExpr(n);       break;
        case NodeKind::ArrowFunctionExpr:   genArrowFunctionExpr(n);break;
        case NodeKind::SequenceExpr:        genSequenceExpr(n);     break;
        case NodeKind::JSXElement:          genJSXElement(n);       break;
        case NodeKind::JSXFragment:         genJSXFragment(n);      break;
        case NodeKind::FunctionDecl:        genFunctionDecl(n);     break;
        default:
            throw CodeGenError("Unhandled expression node kind " +
                               std::to_string(static_cast<int>(n.kind)));
    }
}

void CodeGen::genIdentifier(const Node& n)     { emit(n.name); }
void CodeGen::genNumericLiteral(const Node& n) { emit(n.value); }
void CodeGen::genStringLiteral(const Node& n)  { emit("\"" + escapeString(n.value) + "\""); }
void CodeGen::genBoolLiteral(const Node& n)    { emit(n.boolVal ? "true" : "false"); }

void CodeGen::genTemplateLiteral(const Node& n) {
    emit("`" + n.value + "`");
}

void CodeGen::genBinaryExpr(const Node& n) {
    emit("("); genExpr(*n.object); emit(" " + n.name + " "); genExpr(*n.property); emit(")");
}

void CodeGen::genUnaryExpr(const Node& n) {
    std::string op = n.name;
    bool isPost = op.size() > 4 && op.substr(op.size() - 4) == "post";
    bool isPre  = op.size() > 3 && op.substr(op.size() - 3) == "pre";
    if (isPre) {
        emit(op.substr(0, op.size() - 3));
        genExpr(*n.object);
    } else if (isPost) {
        genExpr(*n.object);
        emit(op.substr(0, op.size() - 4));
    } else {
        emit(op + " ");
        genExpr(*n.object);
    }
}

void CodeGen::genLogicalExpr(const Node& n)  { genBinaryExpr(n); }
void CodeGen::genAssignExpr(const Node& n)   {
    genExpr(*n.object); emit(" " + n.name + " "); genExpr(*n.property);
}

void CodeGen::genCallExpr(const Node& n) {
    genExpr(*n.callee);
    emit("(");
    for (size_t i = 0; i < n.arguments.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.arguments[i]);
    }
    emit(")");
}

void CodeGen::genMemberExpr(const Node& n) {
    genExpr(*n.object);
    if (n.computed) { emit("["); genExpr(*n.property); emit("]"); }
    else             { emit("."); genExpr(*n.property); }
}

void CodeGen::genNewExpr(const Node& n) {
    emit("new ");
    genExpr(*n.callee);
    emit("(");
    for (size_t i = 0; i < n.arguments.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.arguments[i]);
    }
    emit(")");
}

void CodeGen::genConditionalExpr(const Node& n) {
    emit("(");
    genExpr(*n.test); emit(" ? "); genExpr(*n.consequent); emit(" : "); genExpr(*n.alternate);
    emit(")");
}

void CodeGen::genSpreadElement(const Node& n) { emit("..."); genExpr(*n.object); }

void CodeGen::genArrayExpr(const Node& n) {
    emit("[");
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.children[i]);
    }
    emit("]");
}

void CodeGen::genObjectExpr(const Node& n) {
    emit("{ ");
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        const Node& prop = *n.children[i];
        if (prop.name == "...") { emit("..."); genExpr(*prop.init); }
        else {
            emit(prop.name + ": ");
            genExpr(*prop.init);
        }
    }
    emit(" }");
}

void CodeGen::genArrowFunctionExpr(const Node& n) {
    if (n.async_) emit("async ");
    emit("(");
    for (size_t i = 0; i < n.params.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.params[i]);
    }
    emit(") => ");
    if (!n.body.empty()) {
        if (n.body[0]->kind == NodeKind::BlockStmt)
            genBlockStmt(*n.body[0]);
        else
            genExpr(*n.body[0]);
    }
}

void CodeGen::genSequenceExpr(const Node& n) {
    for (size_t i = 0; i < n.children.size(); ++i) {
        if (i) emit(", ");
        genExpr(*n.children[i]);
    }
}

// ---------------------------------------------------------------------------
// JSX lowering
// ---------------------------------------------------------------------------

void CodeGen::emitJSXProps(const Node& openingEl) {
    // Count real (non-spread) attributes for dev mode
    bool hasAttrs = !openingEl.attributes.empty();

    if (!hasAttrs && !opts_.devMode) {
        emit("null");
        return;
    }

    emit("{ ");
    bool first = true;

    for (const auto& attrPtr : openingEl.attributes) {
        const Node& attr = *attrPtr;
        if (!first) emit(", ");
        first = false;

        if (attr.kind == NodeKind::JSXSpreadAttribute) {
            emit("...");
            genExpr(*attr.expression);
        } else {
            emit(attr.name + ": ");
            if (attr.init) {
                if (attr.init->kind == NodeKind::JSXExpressionContainer)
                    genExpr(*attr.init->expression);
                else
                    genExpr(*attr.init);
            } else {
                emit("true");
            }
        }
    }

    // dev mode: inject __source and __self
    if (opts_.devMode) {
        if (!first) emit(", ");
        emit("__self: this, __source: { fileName: \"" +
             escapeString(filename_) + "\", lineNumber: " +
             std::to_string(openingEl.line) + " }");
    }

    emit(" }");
}

void CodeGen::genJSXElement(const Node& n) {
    const Node& opening = *n.openingElement;
    const std::string& pragma = opts_.pragmaCall();
    emit(pragma + "(");

    // First arg: tag (lowercase -> string, uppercase/member -> identifier)
    char firstChar = opening.name.empty() ? '\0' : opening.name[0];
    if (std::islower((unsigned char)firstChar)) {
        emit("\"" + opening.name + "\"");
    } else {
        emit(opening.name);
    }

    emit(", ");
    emitJSXProps(opening);

    // Children — filter empty JSXText after whitespace normalisation
    for (const auto& child : n.children) {
        if (child->kind == NodeKind::JSXText) {
            std::string text = escapeJSXText(child->value);
            if (text.empty()) continue;
            emit(", \"" + escapeString(text) + "\"");
        } else {
            emit(", ");
            genJSXChild(*child);
        }
    }

    emit(")");
}

void CodeGen::genJSXFragment(const Node& n) {
    const std::string& pragma = opts_.pragmaCall();
    const std::string& frag   = opts_.fragmentExpr();
    emit(pragma + "(" + frag + ", null");
    for (const auto& child : n.children) {
        if (child->kind == NodeKind::JSXText) {
            std::string text = escapeJSXText(child->value);
            if (text.empty()) continue;
            emit(", \"" + escapeString(text) + "\"");
        } else {
            emit(", ");
            genJSXChild(*child);
        }
    }
    emit(")");
}

void CodeGen::genJSXChild(const Node& n) {
    if (n.kind == NodeKind::JSXText) {
        std::string text = escapeJSXText(n.value);
        if (!text.empty()) emit("\"" + escapeString(text) + "\"");
    } else if (n.kind == NodeKind::JSXExpressionContainer) {
        if (n.expression)  // null expression == JSX comment {/* */}
            genExpr(*n.expression);
    } else if (n.kind == NodeKind::JSXElement) {
        genJSXElement(n);
    } else if (n.kind == NodeKind::JSXFragment) {
        genJSXFragment(n);
    } else {
        genExpr(n);
    }
}

