// Returns the tag name string, handling Foo.Bar member expressions.
std::string Parser::parseJSXTagName() {
    std::string name = expect(TokenKind::Identifier, "JSX tag name").value;
    while (check(TokenKind::Dot)) {
        advance();
        name += "." + expect(TokenKind::Identifier, "JSX member name").value;
    }
    return name;
}

