// Returns the tag name string, handling Foo.Bar and svg:circle forms.
std::string Parser::parseJSXTagName() {
    std::string name = expect(TokenKind::Identifier, "JSX tag name").value;
    if (check(TokenKind::Colon)) {
        // Namespace: svg:circle
        advance();
        name += ":" + expect(TokenKind::Identifier, "JSX namespace member").value;
    } else {
        while (check(TokenKind::Dot)) {
            advance();
            name += "." + expect(TokenKind::Identifier, "JSX member name").value;
        }
    }
    return name;
}

