NodePtr Parser::parseJSXExprContainer() {
    const Token& lb = expect(TokenKind::LBrace, "{");
    auto n = makeNode(NodeKind::JSXExpressionContainer, lb.line, lb.col);

    // JSX comment: {/* ... */} — the comment was consumed by the lexer's
    // skipWhitespaceAndComments when it re-entered JS mode.  If we immediately
    // see }, treat this as an empty/comment container (expression stays null).
    if (!check(TokenKind::RBrace)) {
        // Spread children: {...items}
        if (check(TokenKind::DotDotDot)) {
            advance();
            auto sp = makeNode(NodeKind::SpreadElement, peek().line, peek().col);
            sp->object = parseAssignExpr();
            n->expression = std::move(sp);
        } else {
            inExpressionContext_ = true;
            n->expression = parseAssignExpr();
            inExpressionContext_ = false;
        }
    }

    expect(TokenKind::RBrace, "}");
    return n;
}

