// Skip tokens until we reach a likely statement boundary.
void Parser::synchronize() {
    while (!atEnd()) {
        TokenKind k = peek().kind;
        // Stop before statement-starter keywords
        if (k == TokenKind::KW_function || k == TokenKind::KW_const  ||
            k == TokenKind::KW_let      || k == TokenKind::KW_var     ||
            k == TokenKind::KW_return   || k == TokenKind::KW_if      ||
            k == TokenKind::KW_for      || k == TokenKind::KW_while   ||
            k == TokenKind::KW_export   || k == TokenKind::KW_import  ||
            k == TokenKind::KW_class)
            return;
        advance();
    }
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------
NodePtr Parser::parse() {
    auto prog = makeNode(NodeKind::Program, 1, 1);
    while (!atEnd()) {
        if (errors_) {
            // Recovery mode: catch errors, synchronize, and continue
            try {
                prog->body.push_back(parseStatement());
            } catch (const ParseError& e) {
                errors_->error(e.what(), e.line, e.col);
                synchronize();
            }
        } else {
            prog->body.push_back(parseStatement());
        }
    }
    return prog;
}

